// CampaignServiceHandler is an implementation of the meurpg.campaigns.v1.CampaignService service.
type CampaignServiceHandler interface {
	// CreateCampaign creates a campaign; the caller becomes its master
	// (MR-001).
	//
	// Safe to retry when the request carries an idempotency_key: a second call with the same key and
	// the same request returns what the first one made and makes nothing; the same key with another
	// request is `invalid_argument`. Without a key the call is not deduplicated.
	CreateCampaign(context.Context, *connect.Request[v1.CreateCampaignRequest]) (*connect.Response[v1.CreateCampaignResponse], error)
	// ListMyCampaigns lists the campaigns the caller is a member of, newest
	// first, with the caller's role in each. It also lists the campaigns where
	// the caller is a pending member (RN-15, MR-024), with only the id, the
	// name, my_role and `awaiting_approval` set, so the player can find their
	// way back to the campaign while they wait.
	//
	// Its request is empty, so clients may call it with HTTP GET: the URL
	// never carries personal data.
	ListMyCampaigns(context.Context, *connect.Request[v1.ListMyCampaignsRequest]) (*connect.Response[v1.ListMyCampaignsResponse], error)
	// GetCampaign returns one campaign. Any member may call it. It only
	// reads, but stays POST-only, because a GET would put the campaign ID in
	// the URL.
	//
	// A pending member (RN-15, MR-024) may call it too, and gets only the
	// campaign's id, name, my_role (ROLE_PLAYER) and `awaiting_approval` set:
	// enough to show "esperando a aprovação do mestre".
	GetCampaign(context.Context, *connect.Request[v1.GetCampaignRequest]) (*connect.Response[v1.GetCampaignResponse], error)
	// ListMembers lists a campaign's members: the master first, then the
	// players in the order they joined. Any member may call it. It only
	// reads, and is POST-only, like GetCampaign.
	//
	// Pending members (RN-15, MR-024) are not listed: they are not members
	// yet. The master sees who is waiting through their characters
	// (CharacterService.ListCharacters, state PENDING), and the ones who have
	// not created a character yet through ListPendingMembers. A pending
	// member who calls it gets `not_found`. (Those two live in their own calls
	// so that this list keeps meaning "people who are in the campaign".)
	ListMembers(context.Context, *connect.Request[v1.ListMembersRequest]) (*connect.Response[v1.ListMembersResponse], error)
	// ListPendingMembers lists the campaign's pending members who have not
	// created a character yet (RN-15, MR-024), in the order they joined, each
	// with when they joined and when they will be removed automatically (30
	// days after joining). Only the campaign's master may call it. It only
	// reads, and is POST-only, like GetCampaign.
	//
	// It is a call of its own, not extra entries in ListMembers, because those
	// people are not members: ListMembers keeps its meaning, and no screen
	// that reads it can mistake them for players. A pending member who already
	// created a character is not here: the master finds them, and approves or
	// rejects them, through CharacterService.ListCharacters.
	ListPendingMembers(context.Context, *connect.Request[v1.ListPendingMembersRequest]) (*connect.Response[v1.ListPendingMembersResponse], error)
	// RemovePendingMember removes a pending member who has not created a
	// character yet (RN-15, MR-024): their membership is deleted. The person
	// loses nothing else (account, other campaigns), and a new invite brings
	// them back. Only the campaign's master may call it. Removing someone who
	// is already gone is `not_found`, so a repeated call tells the app the
	// list is stale.
	//
	// Errors:
	//   - `not_found`: the campaign is not the caller's to manage (see
	//     authorization), or the user has no membership in it.
	//   - `failed_precondition`: the user is an active member (members are not
	//     removed here), or a pending member who already has a character
	//     (the master rejects it with CharacterService.RejectCharacter).
	RemovePendingMember(context.Context, *connect.Request[v1.RemovePendingMemberRequest]) (*connect.Response[v1.RemovePendingMemberResponse], error)
	// CreateInvite creates an invite link for a campaign (MR-002). Only the
	// campaign's master may call it.
	//
	// The response carries the invite's secret token, and this is the only
	// time the server ever returns it: the database keeps only a hash. The app
	// shares it as https://<app>/convite#t=<token>. The token goes in the URL
	// fragment, which browsers never send to a server, so it stays out of
	// request logs and Referer headers (ADR-0009).
	//
	// With `requires_approval`, whoever accepts the invite becomes a pending
	// member instead of a player (RN-15, MR-024): see AcceptInvite.
	CreateInvite(context.Context, *connect.Request[v1.CreateInviteRequest]) (*connect.Response[v1.CreateInviteResponse], error)
	// ListInvites lists a campaign's invites, newest first, without their
	// tokens. Only the campaign's master may call it. It only reads, and is
	// POST-only, like GetCampaign.
	ListInvites(context.Context, *connect.Request[v1.ListInvitesRequest]) (*connect.Response[v1.ListInvitesResponse], error)
	// RevokeInvite stops an invite from working. People who already joined
	// with it stay members. Revoking an invite twice is not an error. Only the
	// campaign's master may call it.
	RevokeInvite(context.Context, *connect.Request[v1.RevokeInviteRequest]) (*connect.Response[v1.RevokeInviteResponse], error)
	// AcceptInvite makes the caller a player of the invite's campaign
	// (MR-003). The app reads the token from the URL fragment and sends it
	// here, in the request body, never in a URL. A signed-out user does the
	// same through sign-in instead: POST /auth/login with
	// intent=campaign_invite and the token as intent_payload (ADR-0009).
	//
	// It is idempotent for members: a member of the campaign (the master
	// included) gets the campaign back with `already_member` set, whatever
	// the state of the invite, and no use of the invite is spent. This holds
	// for a pending member too, with one exception: a pending member who
	// accepts an invite WITHOUT approval (and that works now) is promoted. It
	// spends one use, the membership becomes active, and the character they
	// created and that waits for approval, if any, is approved: an ordinary
	// invite counts as the master's approval (RN-15). The response then has
	// `already_member` false and the full campaign. If they accept an invite
	// with approval, or one that does not work, they stay pending.
	//
	// Invites with approval (RN-15, MR-024). When the invite has
	// `requires_approval`, the caller becomes a pending member, not a player:
	// the returned campaign has `awaiting_approval` set and only its id, name
	// and my_role. The app takes them straight to creating their character
	// (CharacterService.CreateCharacter), which starts PENDING. They become a
	// player when the master approves that character
	// (CharacterService.ApproveCharacter); if the master rejects it
	// (CharacterService.RejectCharacter), the pending membership is deleted
	// and they need a new invite. Accepting it through sign-in works the same
	// way: a new pending member lands on
	// /campanhas/<campaign_id>/personagens/novo, and someone who was already
	// in the campaign on /campanhas/<campaign_id>.
	//
	// Errors:
	//   - `invalid_argument`: the token is empty.
	//   - `not_found`: no invite has this token.
	//   - `failed_precondition`: the invite expired, was revoked or has no
	//     uses left. The error carries an InviteUnusable detail that says
	//     which, so the app can show a clear message.
	AcceptInvite(context.Context, *connect.Request[v1.AcceptInviteRequest]) (*connect.Response[v1.AcceptInviteResponse], error)
	// SetCampaignDiceMode sets how the campaign's players roll dice (RN-18,
	// MR-013): everyone in the app, everyone with their own dice, or each
	// player's choice. Only the campaign's master may call it. It applies
	// from the next roll, and the players' own choices are kept, whatever
	// the mode. Setting the mode it already has is not an error.
	//
	// Errors: `invalid_argument` for an unspecified or unknown mode.
	SetCampaignDiceMode(context.Context, *connect.Request[v1.SetCampaignDiceModeRequest]) (*connect.Response[v1.SetCampaignDiceModeResponse], error)
	// SetMyDicePreference sets how the caller likes to roll in this campaign
	// (RN-18, MR-014). Any active member may call it, the master too. It is
	// always saved, but it only counts while the campaign's mode is
	// DICE_MODE_PLAYERS_CHOOSE. A pending member gets `not_found`.
	//
	// Errors: `invalid_argument` for an unspecified or unknown preference.
	SetMyDicePreference(context.Context, *connect.Request[v1.SetMyDicePreferenceRequest]) (*connect.Response[v1.SetMyDicePreferenceResponse], error)
	// GetTableRules returns the table's rules (MR-025, RN-24): what "Regras da
	// mesa" shows. Any active member may call it, because the page is shown to
	// the whole table. A campaign that never saved its rules gets the defaults
	// (the SRD's: what the app did before the rules existed). A pending member
	// (RN-15) may call it too, to see which ways of making ability scores the
	// table allows while they create their character. It only reads, but stays POST-only, because a GET would
	// put the campaign ID in the URL.
	GetTableRules(context.Context, *connect.Request[v1.GetTableRulesRequest]) (*connect.Response[v1.GetTableRulesResponse], error)
	// SetTableRules replaces all of the table's rules (RN-24). Only the
	// campaign's master may call it. It is one save, as the page has one "Salvar
	// regras": every field is written, so the app sends the whole TableRules it
	// shows. It writes the dice mode (campaigns' own setting, RN-18) in the same
	// transaction, so the page's dice choice and the rest never disagree. It
	// applies from now on: sheets that already exist keep their scores, and a
	// level-up, a creation or a new map takes the rules in force when it happens.
	// Setting what is already saved is not an error.
	//
	// Errors:
	//   - `invalid_argument`: a field is unspecified or unknown; no ability
	//     method is allowed; more than 20 house rules, or one that is empty,
	//     longer than 200 characters or has a line break.
	SetTableRules(context.Context, *connect.Request[v1.SetTableRulesRequest]) (*connect.Response[v1.SetTableRulesResponse], error)
	// SetCampaignXpMode changes how the campaign levels (RN-09) after it was
	// created. Only the campaign's master may call it. The new mode applies from
	// now on; nothing already awarded is converted or changed, the history stays,
	// and going back to the earlier mode is allowed. When XP was already awarded
	// (an award that was not undone, a milestone included), the call needs
	// `confirm`: without it, it answers `failed_precondition` with an
	// XpModeChangeBlocked detail that says how much was awarded, and changes
	// nothing. Setting the mode the campaign already has is not an error and
	// asks for nothing.
	//
	// The mode also decides "Pode subir de nível" (RN-12): by enemies or by gold, the
	// character's XP reaching the next level; by milestones, a mark. So a switch
	// moves the level-ups that are waiting: a character that was ready by XP is
	// not ready by milestones until the master marks it, and one marked for a
	// milestone is not ready by XP until the XP reaches the level. Nothing is
	// written to the sheets: the flag is read from the mode on every read.
	//
	// Errors:
	//   - `invalid_argument`: the mode is unspecified or unknown.
	//   - `failed_precondition`: XP was already awarded and `confirm` is false
	//     (XpModeChangeBlocked).
	SetCampaignXpMode(context.Context, *connect.Request[v1.SetCampaignXpModeRequest]) (*connect.Response[v1.SetCampaignXpModeResponse], error)
}

